    関数を先に呼んでおけば自動的にStore経由の音声が優先される)。"""
    os.makedirs(narration_dir, exist_ok=True)
    results = {}
    for name in FIXED_ENGLISH_TEXTS:
        results[name] = ensure_fixed_english_segment(name, narration_dir, filename_suffix="_charon")
    return results


